{"command": "python3 << 'EOF'
from PIL import Image, ImageDraw, ImageEnhance
im = Image.open('radiograph.jpg').convert('RGB')
def zoom(name, box, s=5, bright=1.0, contrast=1.0):
    x1,y1,x2,y2 = box
    c = im.crop(box)
    c = c.resize((c.width*s, c.height*s), Image.LANCZOS)
    if bright!=1.0: c = ImageEnhance.Brightness(c).enhance(bright)
    if contrast!=1.0: c = ImageEnhance.Contrast(c).enhance(contrast)
    d = ImageDraw.Draw(c)
    for gx in range(x1-x1%50+50, x2, 50):
        lx=(gx-x1)*s; d.line([(lx,0),(lx,c.height)],fill=(255,80,80),width=1)
        if gx%100==0: d.text((lx+2,2),str(gx),fill=(255,255,0))
    for gy in range(y1-y1%50+50, y2, 50):
        ly=(gy-y1)*s; d.line([(0,ly),(c.width,ly)],fill=(255,80,80),width=1)
        if gy%100==0: d.text((2,ly+2),str(gy),fill=(255,255,0))
    c.save(f'{name}.jpg', quality=93); print(name, c.size)

# original, no enhancement
zoom('A_orig', (860, 370, 1060, 620))
